const raw = $input.first().json;
const story_id = raw?.body?.story_id ?? raw?.story_id ?? null;
if (!story_id) throw new Error('story_id not found. Got: ' + JSON.stringify(raw));
console.log('story_id:', story_id);
return [{ json: { story_id } }];

const rows = $input.first().json;
const story = Array.isArray(rows) ? rows[0] : rows;
if (!story || !story.id) throw new Error('Story not found in DB');
const child  = story.children ?? {};
const lang   = story.languages ?? {};
const style  = story.image_styles ?? {};
const photos = story.story_original_images ?? [];
const photo_url = photos.length > 0 ? photos[0].image_url : null;
console.log('Story:', story.id, 'Child:', child.name, 'Theme:', story.theme);
return [{ json: {
  story_id:      story.id,
  child_name:    child.name ?? 'Hero',
  child_age:     child.age  ?? 6,
  theme:         story.theme ?? 'forest',
  user_prompt:   story.user_prompt ?? story.prompt ?? '',
  language_name: lang.name  ?? 'Turkish',
  language_code: lang.code  ?? 'tr',
  image_style:   style.label ?? style.name ?? 'Watercolor',
  page_count:    story.page_count ?? story.total_pages ?? 8,
  llm_model:     story.llm_model ?? 'gpt-4o-mini',
  fal_model:     story.fal_model ?? 'fal-ai/flux/schnell',
  resolution:    story.resolution ?? '768',
  watermark:     story.watermark ?? true,
  photo_url:     photo_url,
} }];

