const response = $input.first().json;
let content = response?.content ?? response?.message?.content ?? response?.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenAI empty response: ' + JSON.stringify(response));
content = content.trim().replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
let parsed;
try { parsed = JSON.parse(content); } catch(e) { throw new Error('JSON parse failed: ' + content.substring(0, 200)); }
if (!parsed.pages) throw new Error('No pages array in response');
const vars = $('Prepare Variables').first().json;
console.log(parsed.pages.length + ' pages. Title: ' + parsed.title);
return parsed.pages.map(page => ({ json: {
  story_id:            vars.story_id,
  story_title:         parsed.title,
  page_no:             page.page_number,
  text:                page.text,
  illustration_prompt: page.illustration_prompt,
  fal_model:           vars.fal_model,
  fal_endpoint:        'https://fal.run/' + vars.fal_model,
  photo_url:           vars.photo_url,
  resolution:          vars.resolution,
  child_name:          vars.child_name,
  page_count:          vars.page_count,
  watermark:           vars.watermark,
} }));

const insertResult = $input.first().json;
const ctx = $('Parse Pages').item.json;
const page_id = insertResult?.id ?? null;
if (!page_id) throw new Error('Page ' + ctx.page_no + ': no ID from Supabase. Got: ' + JSON.stringify(insertResult));
console.log('Page', ctx.page_no, 'saved. ID:', page_id);
const isKontext = ctx.fal_model?.includes('kontext');
const isSchnell = ctx.fal_model?.includes('schnell');
const falBody = { prompt: ctx.illustration_prompt, image_size: 'landscape_4_3', num_images: 1, enable_safety_checker: false };
if (isKontext) { if (ctx.photo_url) falBody.image_url = ctx.photo_url; falBody.num_inference_steps = 28; falBody.guidance_scale = 3.5; }
else if (isSchnell) { falBody.num_inference_steps = 4; }
else { falBody.num_inference_steps = 20; falBody.guidance_scale = 3.5; }
return [{ json: { page_id, story_id: ctx.story_id, page_no: ctx.page_no, fal_endpoint: ctx.fal_endpoint, fal_body: falBody } }];

const data = $input.first().json;
const pages = data.pages ?? [];
if (!pages.length) throw new Error('No pages after aggregate');
const first = Array.isArray(pages[0]) ? pages[0][0] : pages[0];
const story_id = first?.story_id ?? null;
if (!story_id) throw new Error('story_id not found. Got: ' + JSON.stringify(first));
console.log('All pages done. Generating PDF for:', story_id);
return [{ json: { story_id } }];

const r = $input.first().json;
console.log('Story completed! PDF:', r.pdf_url);
return [{ json: { success: true, pdf_url: r.pdf_url } }];
